<script setup lang="ts">
import SelectField from '../../components/SelectField.vue'
import { ref, watch } from 'vue'
import { CheckCircle2, CircleAlert, Search, RefreshCw, Trash2, Info, ArrowLeft, ArrowRight } from '@lucide/vue'
import StatusBadge from '../../components/StatusBadge.vue'
import RunDetail from './RunDetail.vue'
import { api } from '../../app/api'
import { state, perform, notify } from '../../app/state'
import type { Run } from '../../app/types'
import { time, duration, bytes } from '../../app/format'
const tab = ref('succeeded'); const source = ref(''); const age = ref(''); const search = ref(''); const page = ref(0); const total = ref(0); const records = ref<Run[]>([]); const detail = ref<number>()
let loadingRevision=0
async function load() { const revision=++loadingRevision; const query=new URLSearchParams({state:tab.value,source:source.value,limit:'50',offset:String(page.value*50)}); if(age.value) query.set('from',new Date(Date.now()-Number(age.value)*86400000).toISOString()); const payload=await api<{items:Run[];total:number}>(`/runs?${query}`); if(revision!==loadingRevision)return;records.value=payload.items; total.value=payload.total }
watch([tab,source,age],()=>{page.value=0;perform(load)});watch(page,()=>perform(load));watch(()=>state.revision,()=>perform(load),{immediate:true})
async function clear() { if(!window.confirm('清理已结束任务的原始日志？运行记录、来源尝试与错误摘要会保留。')) return; const payload=await api<{cleared:number}>('/logs/clear','POST');notify(`已清理 ${payload.cleared} 份日志`);await load() }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">EXECUTION HISTORY</span><h1>运行记录<span>.</span></h1><p>成功留痕，失败可查。每次同步都有完整记录。</p></div><div class="heading-actions"><button class="button" @click="perform(clear)"><Trash2 :size="16"/>清理日志</button><button class="button" @click="perform(load)"><RefreshCw :size="16"/>刷新</button></div></div><div class="tabs"><button :class="{active:tab==='succeeded'}" @click="tab='succeeded'"><CheckCircle2 :size="17"/>成功记录</button><button :class="{active:tab==='failure'}" @click="tab='failure'"><CircleAlert :size="17"/>失败记录</button></div><div class="panel"><div class="filter-toolbar"><label class="search-field"><Search :size="17"/><input v-model="search" placeholder="搜索当前页名称或错误…" aria-label="搜索当前页记录"/></label><SelectField v-model="source" aria-label="按同步源筛选" :options="[{ value: '', label: '全部同步源' }, ...(state.config?.config.sources ?? []).map(item => ({ value: item.id, label: item.name }))]" /><SelectField v-model="age" aria-label="按时间筛选" :options="[{ value: '', label: '全部时间' }, { value: '1', label: '最近 24 小时' }, { value: '7', label: '最近 7 天' }, { value: '30', label: '最近 30 天' }]" /><span class="filter-count">共 {{total}} 项 · 50 项 / 页</span></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>同步源</th><th>状态</th><th>耗时 / 数据量</th><th>{{tab==='succeeded'?'处理结果':'失败原因'}}</th><th>详情</th></tr></thead><tbody><tr v-for="run in records.filter(item=>`${item.name} ${item.error_code} ${item.error}`.toLowerCase().includes(search.toLowerCase()))" :key="run.id"><td><strong>{{time(run.created_at).slice(0,10)}}</strong><small>{{time(run.created_at).slice(-8)}}</small></td><td><strong>{{run.name}}</strong><small>{{run.type}} · #{{run.id}}</small></td><td><StatusBadge :state="run.state"/></td><td><strong>{{duration(run.elapsed_seconds)}}</strong><small>{{bytes(run.progress.bytes)}}</small></td><td class="record-reason"><template v-if="run.error_code"><strong>{{run.error_code}}</strong><p>{{run.error}}</p></template><template v-else>成功发布<template v-if="run.type==='github_release'||run.progress.success>0"> · {{run.progress.success}} 项</template><span v-if="run.progress.skipped"> · 复用 {{run.progress.skipped}} 项</span></template></td><td><button class="icon-button" aria-label="查看记录详情" @click="detail=run.id"><Info :size="17"/></button></td></tr><tr v-if="!records.length"><td colspan="6" class="empty-state"><component :is="tab==='succeeded'?CheckCircle2:CircleAlert" :size="32"/><h3>暂无{{tab==='succeeded'?'成功':'失败'}}记录</h3><p>任务结束后，记录会自动保存在这里。</p></td></tr></tbody></table></div><div class="pagination"><span>第 {{page+1}} 页 / {{Math.max(1,Math.ceil(total/50))}} 页</span><button class="button compact" :disabled="page===0" @click="page--"><ArrowLeft :size="15"/>上一页</button><button class="button compact" :disabled="(page+1)*50>=total" @click="page++">下一页<ArrowRight :size="15"/></button></div></div><RunDetail v-if="detail" :id="detail" @close="detail=undefined"/></section></template>
